import { NextRequest, NextResponse } from "next/server";
import { DEMO_CREDENTIALS } from "@/lib/auth-config";
import { resend } from "@/lib/resend";
import { saveOtp } from "../otp-store";

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { email, password } = body as { email?: string; password?: string };

    if (!email || !password) {
      return NextResponse.json({ error: "Email and password are required." }, { status: 400 });
    }

    const user = DEMO_CREDENTIALS.find(
      (demo) => demo.email.toLowerCase() === email.toLowerCase() && demo.password === password
    );

    if (!user) {
      return NextResponse.json({ error: "Invalid credentials." }, { status: 401 });
    }

    const otp = Math.floor(100000 + Math.random() * 900000).toString();
    saveOtp(user.email, otp, user);

    if (!process.env.RESEND_API_KEY) {
      // In development, log OTP so it's still testable without email setup.
      // eslint-disable-next-line no-console
      console.log(`OTP for ${user.email}: ${otp} (RESEND_API_KEY not set, email not sent)`);
    } else {
      await resend.emails.send({
        from: "Calaya Taskly <noreply@calayaengineering.com>",
        to: [user.email],
        subject: "Your Calaya Taskly verification code",
        text: `Your one-time verification code is ${otp}. It expires in 5 minutes.`,
      });
    }

    return NextResponse.json({
      success: true,
      role: user.role,
      route: user.route,
    });
  } catch (error) {
    // eslint-disable-next-line no-console
    console.error("Error in send-otp route:", error);
    return NextResponse.json({ error: "Failed to send OTP." }, { status: 500 });
  }
}

